-- core_audit_log (data §2.1, §3.1, §10; domain model §2.5, K-7; identity and tenancy §7). Range
-- partitioned by month on occurred_at, so the two-year retention is a partition drop, never a
-- DELETE. PK (id, occurred_at): a key of a partitioned table must contain the partition key.
-- A nullable-account table (data §2.4): platform actors and refused cross-tenant calls write rows
-- with no account.
--
-- Immutability, three lines (data §3.1, §3.2):
--   1. core_make_append_only on the parent: the runtime roles keep SELECT and INSERT only, and the
--      row trigger BEFORE UPDATE OR DELETE is cloned onto every partition, existing and future
--      (PostgreSQL 16 CREATE TRIGGER notes); the statement trigger BEFORE TRUNCATE covers the
--      parent (statement triggers are not cloned).
--   2. Partitions grant the runtime roles nothing (PLAT-5 plan §6, review M-4): every read and
--      write goes through the parent, its triggers and its policies (a query naming a partition
--      would see that partition's policies, of which there are none). The default privileges of
--      0001 would grant DML on each new partition; core_ensure_audit_partitions revokes it at once.
--   3. Only elx_owner can detach or drop a partition, and core_drop_audit_partitions_before refuses
--      any partition newer than 24 months.
CREATE TABLE "core_audit_log" (
	"id" uuid DEFAULT core_uuidv7() NOT NULL,
	"occurred_at" timestamp with time zone DEFAULT now() NOT NULL,
	"actor_type" text NOT NULL,
	"actor_id" uuid,
	"account_id" uuid,
	"target_type" text NOT NULL,
	"target_id" text NOT NULL,
	"action" text NOT NULL,
	"before" jsonb,
	"after" jsonb,
	"request_id" text NOT NULL,
	"ip" "inet",
	"user_agent" text,
	"reason" text,
	CONSTRAINT "core_audit_log_id_occurred_at_pk" PRIMARY KEY("id","occurred_at"),
	CONSTRAINT "core_audit_log_actor_type_check" CHECK ("core_audit_log"."actor_type" IN ('user', 'api_key', 'driver', 'system', 'platform_user')),
	CONSTRAINT "core_audit_log_actor_id_check" CHECK ("core_audit_log"."actor_id" IS NOT NULL OR "core_audit_log"."actor_type" = 'system'),
	CONSTRAINT "core_audit_log_action_check" CHECK ("core_audit_log"."action" ~ '^[a-z]+\.[a-z_]+\.[a-z_]+$')
) PARTITION BY RANGE ("occurred_at");
