-- The template policies of data §4.3 (0003). tenant_isolation keeps the template's USING and WITH
-- CHECK: a tenant transaction reads and inserts its own account's rows only (UPDATE and DELETE are
-- withheld by the grants and the trigger). NULL-account rows match no tenant. elx_platform sees
-- every row through platform_access; its repositories carry their own predicates.
CREATE POLICY tenant_isolation ON core_audit_log TO elx_app
  USING (account_id = NULLIF(current_setting('elx.account_id', true), '')::uuid)
  WITH CHECK (account_id = NULLIF(current_setting('elx.account_id', true), '')::uuid);
